//! End-to-end check of the WhatsApp and Telegram samples (generated by tests/samples/whatsapp_telegram.py):
//! plan → parse → slice → write → validate → round trip, compared with examples/sample/expected/*.json.

use rv_rsmf_core::model::SourceKind;
use rv_rsmf_core::rsmf::{self, WriteOptions};
use rv_rsmf_core::sources::{self, DateOrder, ParseError, ParseOptions};
use serde_json::Value;
use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

fn sample_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../examples/sample")
}

fn evidence_files() -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = walkdir::WalkDir::new(sample_dir().join("evidence"))
        .into_iter()
        .filter_map(Result::ok)
        .filter(|e| e.file_type().is_file())
        .map(|e| e.into_path())
        .collect();
    v.sort();
    v
}

fn expected() -> Vec<(String, Value)> {
    let mut out = vec![];
    for e in std::fs::read_dir(sample_dir().join("expected")).unwrap() {
        let p = e.unwrap().path();
        if p.extension().is_some_and(|x| x == "json") {
            let v: Value = serde_json::from_slice(&std::fs::read(&p).unwrap()).unwrap();
            if matches!(v["source"].as_str(), Some("whatsapp" | "telegram")) {
                out.push((p.file_stem().unwrap().to_string_lossy().to_string(), v));
            }
        }
    }
    out.sort_by(|a, b| a.0.cmp(&b.0));
    out
}

#[test]
fn samples_convert_to_valid_round_tripping_rsmf() {
    let cases = expected();
    assert_eq!(
        cases.len(),
        5,
        "expected JSON files for the 5 WhatsApp/Telegram samples"
    );
    let (exports, _) = sources::plan_exports(&evidence_files(), None);
    for (name, want) in cases {
        let primary = sample_dir()
            .join("evidence")
            .join(want["path"].as_str().unwrap());
        let export = exports
            .iter()
            .find(|e| e.primary == primary)
            .unwrap_or_else(|| panic!("{name}: no export planned for {}", primary.display()));
        let kind = SourceKind::parse(want["source"].as_str().unwrap()).unwrap();
        assert_eq!(export.kind, kind, "{name}: detected kind");
        let tz: Option<chrono_tz::Tz> = want["options"]["timezone"]
            .as_str()
            .map(|t| t.parse().unwrap());
        let order = want["options"]["date_order"]
            .as_str()
            .map(|o| DateOrder::parse(o).unwrap());
        let opts = ParseOptions {
            timezone: tz,
            date_order: order,
            ..ParseOptions::default()
        };
        // The examiner's decisions are never guessed.
        if order.is_some() {
            let r = sources::parse(
                export,
                &ParseOptions {
                    date_order: None,
                    ..opts.clone()
                },
            );
            assert!(
                matches!(r, Err(ParseError::NeedsDateOrder { ref evidence, .. }) if !evidence.is_empty()),
                "{name}: without --date-order: {r:?}"
            );
        }
        if kind.needs_timezone() {
            let r = sources::parse(
                export,
                &ParseOptions {
                    timezone: None,
                    ..opts.clone()
                },
            );
            assert_eq!(
                r,
                Err(ParseError::NeedsTimezone),
                "{name}: without --timezone"
            );
        }
        let p = sources::parse(export, &opts).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(p.source, Some(kind));

        let slice_tz = tz.unwrap_or(chrono_tz::UTC);
        let wo = WriteOptions {
            tz: slice_tz,
            custodian: None,
            platform: rsmf::platform_for(kind, None),
            generator: "rv-rsmf test".into(),
            collection_seed: format!("TEST-{name}"),
        };
        let slices = rsmf::slice(&p, slice_tz);
        let (d1, d2) = (tempfile::tempdir().unwrap(), tempfile::tempdir().unwrap());
        let (mut packed, mut missing, mut events) = (0usize, 0usize, 0usize);
        for s in &slices {
            let (ws, b1) = rsmf::write_slice(&p, s, &wo, d1.path()).unwrap();
            let (_, b2) = rsmf::write_slice(&p, s, &wo, d2.path()).unwrap();
            assert_eq!(b1, b2, "{name}: writing twice must give identical bytes");
            let (v, _) = rsmf::validate_file(&ws.path).unwrap();
            assert!(v.ok(), "{name} {}: {v:?}", ws.path.display());
            let rt = rsmf::roundtrip(&ws).unwrap();
            assert!(rt.is_empty(), "{name}: {rt:?}");
            packed += ws.attachments.len();
            missing += ws.missing_attachments;
            events += ws.events;
        }
        assert_eq!(events, p.events.len(), "{name}: every event written once");
        let n = |k: &str| want[k].as_u64().unwrap() as usize;
        assert_eq!(
            p.conversations.len(),
            n("conversations"),
            "{name}: conversations"
        );
        assert_eq!(p.events.len(), n("events"), "{name}: events");
        assert_eq!(
            packed,
            n("attachments_packed"),
            "{name}: packed attachments"
        );
        assert_eq!(
            missing,
            n("attachments_missing"),
            "{name}: missing attachments"
        );
        let got: BTreeSet<&str> = p.findings.iter().map(|f| f.code.as_str()).collect();
        let exp: BTreeSet<&str> = want["findings"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        assert_eq!(got, exp, "{name}: findings");
        // Every event is traceable to its place in the export, with the original time text.
        for e in &p.events {
            assert!(
                !e.source.file.is_empty() && !e.source_time.is_empty(),
                "{name}: {e:?}"
            );
            assert!(e.timestamp.is_some(), "{name}: {e:?}");
        }
    }
}

#[test]
fn sample_details() {
    let (exports, _) = sources::plan_exports(&evidence_files(), None);
    let get = |rel: &str| {
        let primary = sample_dir().join("evidence").join(rel);
        exports
            .iter()
            .find(|e| e.primary == primary)
            .unwrap()
            .clone()
    };
    let paris = Some("Europe/Paris".parse().unwrap());
    // Android: multi-line message, author with ": ", number-only participant, inferred dmy.
    let p = sources::parse(
        &get("whatsapp-android-en/WhatsApp Chat with Ana Ruiz.txt"),
        &ParseOptions {
            timezone: paris,
            ..ParseOptions::default()
        },
    )
    .unwrap();
    assert_eq!(p.conversations[0].display, "Ana Ruiz");
    assert_eq!(p.facts["variant"], "android");
    let e4 = &p.events[3];
    assert_eq!(
        e4.body,
        "Hola! Plan for the 14th:\n1. Kick-off at 10:00\n2. Review: budget & timeline"
    );
    assert_eq!((e4.source.line, e4.source.line_end), (4, 6));
    assert_eq!(
        rsmf::rsmf_time(&e4.timestamp.unwrap()),
        "2026-03-02T09:00:00Z"
    );
    assert_eq!(p.events[10 - 1].kind, rv_rsmf_core::model::EventType::Leave);
    let inferred = p
        .findings
        .iter()
        .find(|f| f.code == "DATE_ORDER_INFERRED")
        .unwrap();
    assert_eq!(inferred.params["line"], "11");
    assert_eq!(inferred.params["example"], "13/03/2026, 18:45");
    // iOS zip: 12-hour Spanish clock with U+202F, attachment from the zip, Direct chat.
    let p = sources::parse(
        &get("whatsapp-ios-es.zip"),
        &ParseOptions {
            timezone: Some("America/Bogota".parse().unwrap()),
            ..ParseOptions::default()
        },
    )
    .unwrap();
    assert_eq!(p.facts["variant"], "ios");
    assert_eq!(p.events[3].source.file, "_chat.txt");
    assert_eq!(
        rsmf::rsmf_time(&p.events[3].timestamp.unwrap()),
        "2026-03-05T02:15:02Z"
    );
    assert_eq!(
        rsmf::rsmf_time(&p.events[4].timestamp.unwrap()),
        "2026-03-15T05:05:44Z"
    );
    assert_eq!(
        p.conversations[0].kind,
        rv_rsmf_core::model::ConversationType::Direct
    );
    // Telegram: reply → parent, edited time, two conversations.
    let p = sources::parse(&get("telegram/result.json"), &ParseOptions::default()).unwrap();
    assert_eq!(p.events[1].parent.as_deref(), Some("e-000001"));
    assert_eq!(p.events[2].custom["edited_utc"], "2026-03-02T09:12:00Z");
    assert_eq!(
        p.events[1].body,
        "Merci ! Voir le dossier [https://example.org/dossier] et vite."
    );
}
